<?php
namespace GlpiPlugin\Projectplus;
use DBmysql; use Session;
if (!defined('GLPI_ROOT')) die("Sorry. You can't access directly to this file");
class DocumentField {
 public static function getTable($c=null):string{return 'glpi_plugin_projectplus_documentfields';}
 public static function types():array{return ['text'=>__('Texto curto','projectplus'),'textarea'=>__('Texto longo','projectplus'),'number'=>__('Número','projectplus'),'date'=>__('Data','projectplus'),'select'=>__('Lista suspensa','projectplus'),'section'=>__('Título de seção','projectplus')];}
 public static function get(int $entity,string $type,bool $active=false):array{global $DB;self::ensureDefaults($entity,$type);$where=['entities_id'=>$entity,'document_type'=>$type];if($active)$where['is_active']=1;return iterator_to_array($DB->request(['FROM'=>self::getTable(),'WHERE'=>$where,'ORDER'=>['sort_order ASC','id ASC']]),false);}
 private static function ensureDefaults(int $entity,string $type):void{global $DB;if($DB->request(['COUNT'=>'c','FROM'=>self::getTable(),'WHERE'=>['entities_id'=>$entity,'document_type'=>$type]])->current()['c']>0)return;$sets=['tap'=>[['Dados iniciais do projeto','section',0],['Nome do projeto','text',1],['Status do projeto','text',1],['Classificação inicial (Tipo)','text',1],['Categoria','text',1],['Cesta Portfólio','text',1],['Ação PDTIC','text',1],['Prioridade','number',1],['Origem da solicitação','text',1],['Data da solicitação','date',1],['Data de início','date',1],['Data estimada de finalização','date',1],['Dados do solicitante','section',0],['Área do solicitante','text',1],['Nome do solicitante','text',1],['E-mail do solicitante','text',1],['Ponto focal','text',0],['E-mail do ponto focal','text',0],['Visão geral','textarea',1],['Objetivos','textarea',1],['Justificativa','textarea',1],['Descrição da entrega','textarea',1],['Marcos (principais entregas)','textarea',1],['Escopo do produto e/ou serviço','section',0],['Características do produto e/ou serviço','textarea',1],['Exclusões, fora do escopo e restrições','textarea',0],['Organização e recursos internos','section',0],['Pessoas e responsabilidades','textarea',1],['Dinâmica dos trabalhos','textarea',1],['Recursos','textarea',0],['Bases de conhecimento','textarea',0],['Riscos','textarea',0],['Cronograma','textarea',1],['Entregas previstas do projeto','textarea',1]],'tep'=>[['Identificação do projeto','section',0],['Nome do projeto','text',1],['Período de execução','text',1],['Resumo executivo','textarea',1],['Entregas realizadas','textarea',1],['Resultados alcançados','textarea',1],['Evidências e links','textarea',0],['Pendências e questões em aberto','textarea',0],['Lições aprendidas','textarea',0],['Recomendações e próximos passos','textarea',0]],'ta'=>[['Identificação','section',0],['Nome do projeto','text',1],['Entrega','textarea',1],['Requisitos e critérios de aceitação','textarea',1],['Questões em aberto','textarea',0],['Informações adicionais','textarea',0],['Aceite da entrega','section',0],['Nome do chefe de divisão','text',1],['Nome do diretor','text',1],['Data do aceite','date',1]]];foreach(($sets[$type]??[])as$i=>$f)$DB->insert(self::getTable(),['entities_id'=>$entity,'document_type'=>$type,'label'=>$f[0],'field_type'=>$f[1],'is_required'=>$f[2],'is_active'=>1,'sort_order'=>($i+1)*10,'date_creation'=>date('Y-m-d H:i:s'),'date_mod'=>date('Y-m-d H:i:s')]);}
 public static function one(int $id,int $entity,string $type):?array{global $DB;$r=$DB->request(['FROM'=>self::getTable(),'WHERE'=>['id'=>$id,'entities_id'=>$entity,'document_type'=>$type],'LIMIT'=>1])->current();return $r?:null;}
 public static function save(int $entity,string $type,array $in):bool{global $DB;if(!in_array($type,['tap','tep','ta'],true)||!Session::haveAccessToEntity($entity,true))return false;$label=trim((string)($in['label']??''));$ft=(string)($in['field_type']??'text');if($label===''||!isset(self::types()[$ft]))return false;$data=['label'=>substr($label,0,255),'description'=>trim((string)($in['description']??'')),'field_type'=>$ft,'values'=>trim((string)($in['values']??'')),'is_required'=>$ft==='section'?0:(int)!empty($in['is_required']),'is_active'=>(int)!empty($in['is_active']),'sort_order'=>max(0,(int)($in['sort_order']??0)),'date_mod'=>date('Y-m-d H:i:s')];$id=(int)($in['id']??0);if($id&&self::one($id,$entity,$type))return(bool)$DB->update(self::getTable(),$data,['id'=>$id]);return(bool)$DB->insert(self::getTable(),$data+['entities_id'=>$entity,'document_type'=>$type,'date_creation'=>date('Y-m-d H:i:s')]);}
 public static function delete(int $id,int $entity,string $type):bool{global $DB;return Session::haveAccessToEntity($entity,true)&&self::one($id,$entity,$type)!==null&&(bool)$DB->delete(self::getTable(),['id'=>$id]);}
}
